CREATE OR REPLACE FUNCTION app_private.cancel_vendor_order(p_order_id uuid, p_vendor_user_id uuid)
 RETURNS TABLE(order_id uuid, university_id uuid)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  selected public.orders%rowtype;
begin
  select orders.* into selected
  from public.orders orders
  join public.agent_profiles profiles on profiles.id = orders.vendor_profile_id
  where orders.id = p_order_id and profiles.user_id = p_vendor_user_id
    and profiles.status = 'ACTIVE'
  for update of orders;

  if not found or selected.status <> 'PENDING_PAYMENT' then
    raise exception using errcode = 'P0001', message = 'ORDER_NOT_CANCELLABLE';
  end if;

  update public.vendor_products products
  set stock_quantity = products.stock_quantity + reservations.quantity,
      updated_at = now()
  from public.inventory_reservations reservations
  where reservations.order_id = selected.id
    and reservations.product_id = products.id
    and reservations.status = 'HELD';

  update public.inventory_reservations
  set status = 'RELEASED'
  where order_id = selected.id and status = 'HELD';

  update public.delivery_jobs
  set status = 'CANCELLED', updated_at = now()
  where order_id = selected.id and status = 'PAYMENT_PENDING';

  update public.orders
  set status = 'CANCELLED', updated_at = now()
  where id = selected.id and status = 'PENDING_PAYMENT';

  return query select selected.id, selected.university_id;
end;
$function$
CREATE OR REPLACE FUNCTION app_private.cleanup_request_rate_limits()
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  deleted_count integer;
begin
  delete from app_private.request_rate_limits
  where updated_at < now() - interval '7 days'
    and (blocked_until is null or blocked_until < now());
  get diagnostics deleted_count = row_count;
  return deleted_count;
end;
$function$
CREATE OR REPLACE FUNCTION app_private.expire_stale_commerce()
 RETURNS TABLE(reservations_released integer, orders_cancelled integer, bookings_cancelled integer)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  reservation_record record;
  affected_order_ids uuid[] := array[]::uuid[];
begin
  reservations_released := 0;
  orders_cancelled := 0;
  bookings_cancelled := 0;

  for reservation_record in
    select reservations.id, reservations.order_id, reservations.product_id, reservations.quantity
    from public.inventory_reservations reservations
    join public.orders orders on orders.id = reservations.order_id
    where reservations.status = 'HELD' and reservations.expires_at <= now()
      and orders.status = 'PENDING_PAYMENT'
    order by reservations.id
    for update of reservations skip locked
  loop
    update public.vendor_products
    set stock_quantity = stock_quantity + reservation_record.quantity,
        updated_at = now()
    where id = reservation_record.product_id;

    update public.inventory_reservations
    set status = 'RELEASED'
    where id = reservation_record.id and status = 'HELD';

    if found then
      reservations_released := reservations_released + 1;
      affected_order_ids := array_append(affected_order_ids, reservation_record.order_id);
    end if;
  end loop;

  if cardinality(affected_order_ids) > 0 then
    update public.orders orders
    set status = 'CANCELLED', updated_at = now()
    where orders.id = any(affected_order_ids)
      and orders.status = 'PENDING_PAYMENT'
      and not exists (
        select 1 from public.inventory_reservations reservations
        where reservations.order_id = orders.id and reservations.status = 'HELD'
      );
    get diagnostics orders_cancelled = row_count;

    update public.delivery_jobs jobs
    set status = 'CANCELLED', updated_at = now()
    where jobs.order_id = any(affected_order_ids)
      and jobs.status = 'PAYMENT_PENDING';
  end if;

  update public.tutorial_bookings bookings
  set status = 'CANCELLED', updated_at = now()
  where bookings.status = 'PENDING_PAYMENT'
    and bookings.payment_expires_at <= now();
  get diagnostics bookings_cancelled = row_count;

  return next;
end;
$function$
CREATE OR REPLACE FUNCTION app_private.bootstrap_platform_admin(p_user_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('kampusone:platform-admin-bootstrap', 0)
  );

  if exists (select 1 from public.operator_roles) then
    raise exception using errcode = 'P0001', message = 'ADMIN_BOOTSTRAP_ALREADY_COMPLETED';
  end if;

  if not exists (
    select 1 from public.users users
    where users.id = p_user_id
      and users.deleted_at is null
      and users.status::text = 'ACTIVE'
      and users.email_verified_at is not null
  ) then
    raise exception using errcode = 'P0002', message = 'ADMIN_BOOTSTRAP_USER_UNAVAILABLE';
  end if;

  insert into public.operator_roles (user_id, university_id, role, granted_by)
  values (p_user_id, null, 'PLATFORM_ADMIN', p_user_id);

  return true;
end;
$function$
CREATE OR REPLACE FUNCTION app_private.check_and_consume_password_reset(p_token_id uuid, p_token_hash text, p_password_hash text)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  selected public.verification_tokens%rowtype;
begin
  select tokens.* into selected
  from public.verification_tokens tokens
  where tokens.id = p_token_id and tokens.type::text = 'PASSWORD_RESET'
  for update;

  if not found then return 'INVALID'; end if;
  if selected.used_at is not null then return 'USED'; end if;
  if selected.expires_at <= now() then return 'EXPIRED'; end if;
  if selected.attempts >= 5 then return 'LOCKED'; end if;

  if selected.token_hash is distinct from p_token_hash then
    update public.verification_tokens
    set attempts = attempts + 1
    where id = selected.id;
    if selected.attempts + 1 >= 5 then return 'LOCKED'; end if;
    return 'INCORRECT';
  end if;

  update public.verification_tokens
  set used_at = coalesce(used_at, now())
  where user_id = selected.user_id and type::text = 'PASSWORD_RESET' and used_at is null;
  update public.users
  set password_hash = p_password_hash, updated_at = now()
  where id = selected.user_id;
  update public.refresh_tokens
  set revoked_at = coalesce(revoked_at, now())
  where user_id = selected.user_id;
  return 'UPDATED';
end;
$function$
CREATE OR REPLACE FUNCTION app_private.consume_request_rate_limit(p_scope text, p_key_hash text, p_limit integer, p_window_seconds integer, p_block_seconds integer)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  selected app_private.request_rate_limits%rowtype;
begin
  if p_limit < 1 or p_window_seconds < 1 or p_block_seconds < 1 then
    raise exception using errcode = '22023', message = 'INVALID_RATE_LIMIT_CONFIGURATION';
  end if;

  select limits.* into selected
  from app_private.request_rate_limits limits
  where limits.scope = p_scope and limits.key_hash = p_key_hash
  for update;

  if not found then
    insert into app_private.request_rate_limits (scope, key_hash)
    values (p_scope, p_key_hash);
    return true;
  end if;

  if selected.blocked_until is not null and selected.blocked_until > now() then
    update app_private.request_rate_limits set updated_at = now()
    where scope = p_scope and key_hash = p_key_hash;
    return false;
  end if;

  if selected.window_started_at <= now() - pg_catalog.make_interval(secs => p_window_seconds) then
    update app_private.request_rate_limits
    set window_started_at = now(), attempts = 1, blocked_until = null, updated_at = now()
    where scope = p_scope and key_hash = p_key_hash;
    return true;
  end if;

  if selected.attempts >= p_limit then
    update app_private.request_rate_limits
    set blocked_until = now() + pg_catalog.make_interval(secs => p_block_seconds), updated_at = now()
    where scope = p_scope and key_hash = p_key_hash;
    return false;
  end if;

  update app_private.request_rate_limits
  set attempts = attempts + 1, updated_at = now()
  where scope = p_scope and key_hash = p_key_hash;
  return true;
end;
$function$
